effect.shader:
void main() {
    // A fase total soma a parte que anda sozinha (acTime * speed) com a parte
    // que o usuário controla por keyframe. Zerar `speed` deixa a fase 100% nas
    // mãos de quem edita.
    float t = acTime * speed + radians(phase);

    // Amplitude vem em pixels e precisa virar coordenada de textura, senão o
    // efeito ficaria mais forte em projeto pequeno e fraco em 4K.
    vec2 amp = amplitude * acEscalaDePixel * acTexelSize;

    vec2 offset = vec2(0.0);

    if (direction == 0 || direction == 2) {
        offset.x = sin(acScreenNorm.y * frequency * 6.28318 + t) * amp.x;
    }
    if (direction == 1 || direction == 2) {
        // O deslocamento em 1.7 tira as duas ondas de sincronia. Se as duas
        // usassem a mesma fase, o resultado seria um movimento diagonal
        // engessado em vez de algo que parece líquido.
        offset.y = sin(acScreenNorm.x * frequency * 6.28318 + t * 1.7) * amp.y;
    }

    vec2 uv = acScreenNorm + offset;

    // Fora dos limites da camada não existe conteúdo. Devolver transparente é
    // mais honesto que deixar o CLAMP_TO_EDGE esticar a borda em faixas.
    if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) {
        fragColor = vec4(0.0);
        return;
    }

    fragColor = texture(inputImg, uv);
}
